    printf("PPSETMODE 0x%lx\n", (unsigned long)PPSETMODE);
    printf("PPRSTATUS 0x%lx\n", (unsigned long)PPRSTATUS);
    printf("PPRCONTROL 0x%lx\n", (unsigned long)PPRCONTROL);
