    printf("PPCLAIM 0x%lx\n", (unsigned long)PPCLAIM);
    printf("PPRELEASE 0x%lx\n", (unsigned long)PPRELEASE);
    printf("PPYIELD 0x%lx\n", (unsigned long)PPYIELD);
    printf("PPEXCL 0x%lx\n", (unsigned long)PPEXCL);
    printf("PPDATADIR 0x%lx\n", (unsigned long)PPDATADIR);
    printf("PPNEGOT 0x%lx\n", (unsigned long)PPNEGOT);
    printf("PPWCTLONIRQ 0x%lx\n", (unsigned long)PPWCTLONIRQ);
    printf("PPCLRIRQ 0x%lx\n", (unsigned long)PPCLRIRQ);
    printf("PPSETPHASE 0x%lx\n", (unsigned long)PPSETPHASE);
    printf("PPGETTIME 0x%lx\n", (unsigned long)PPGETTIME);
    printf("PPSETTIME 0x%lx\n", (unsigned long)PPSETTIME);
    printf("PPGETMODES 0x%lx\n", (unsigned long)PPGETMODES);
    printf("PPGETMODE 0x%lx\n", (unsigned long)PPGETMODE);
    printf("PPGETPHASE 0x%lx\n", (unsigned long)PPGETPHASE);
    printf("PPGETFLAGS 0x%lx\n", (unsigned long)PPGETFLAGS);
    printf("PPSETFLAGS 0x%lx\n", (unsigned long)PPSETFLAGS);

    printf("IEEE1284_MODE_NIBBLE 0x%x\n", IEEE1284_MODE_NIBBLE);
    printf("IEEE1284_MODE_BYTE 0x%x\n", IEEE1284_MODE_BYTE);
    printf("IEEE1284_MODE_COMPAT 0x%x\n", IEEE1284_MODE_COMPAT);
    printf("IEEE1284_MODE_BECP 0x%x\n", IEEE1284_MODE_BECP);
    printf("IEEE1284_MODE_ECP 0x%x\n", IEEE1284_MODE_ECP);
    printf("IEEE1284_MODE_ECPRLE 0x%x\n", IEEE1284_MODE_ECPRLE);
    printf("IEEE1284_MODE_ECPSWE 0x%x\n", IEEE1284_MODE_ECPSWE);
    printf("IEEE1284_MODE_EPP 0x%x\n", IEEE1284_MODE_EPP);
    printf("IEEE1284_MODE_EPPSL 0x%x\n", IEEE1284_MODE_EPPSL);
    printf("IEEE1284_MODE_EPPSWE 0x%x\n", IEEE1284_MODE_EPPSWE);
    printf("IEEE1284_DEVICEID 0x%x\n", IEEE1284_DEVICEID);
    printf("IEEE1284_EXT_LINK 0x%x\n", IEEE1284_EXT_LINK);
    printf("IEEE1284_ADDR 0x%x\n", IEEE1284_ADDR);
    printf("IEEE1284_DATA 0x%x\n", IEEE1284_DATA);

    printf("PP_FASTWRITE 0x%x\n", PP_FASTWRITE);
    printf("PP_FASTREAD 0x%x\n", PP_FASTREAD);
    printf("PP_W91284PIC 0x%x\n", PP_W91284PIC);

    return 0;
}

